      "role": "protagonist",
      "identity": "火星基地植物学家 / 地球最后幸存者之一",
      "traits": ["坚韧", "深情", "理性中带着疯狂", "强迫症"],
      "overt_motivation": "在火星基地生存下去，等待救援（表面）",
      "covert_motivation": "维持与“妻子”的诡异共生关系，拒绝承认孤独",
      "secret_fear": "彻底的清醒（承认妻子已死，承认身后空无一人）",
      "misperception_of_other": "认为“她”是真实的量子幽灵，而非自己的幻觉",
      "hidden_connection": "通过三年前的信号和当前的氧气消耗数据与“她”连接"
    },
    {
      "name": "林晚",
      "role": "deuteragonist",
      "identity": "地球通讯员（已故）/ 火星基地的“幽灵”",
      "traits": ["温柔", "调皮", "神秘", "守护者"],
      "overt_motivation": "陪伴沈长庚",
      "covert_motivation": "作为沈长庚潜意识的投射，保护他的精神不崩溃",
      "secret_fear": "沈长庚离开火星（意味着她的消失）",
      "misperception_of_other": "无（作为高维或潜意识存在，她全知）",
      "hidden_connection": "她是沈长庚记忆与火星特殊磁场结合的产物"
