  "supporting_characters": [
    {
      "name": "基地主控AI（代号：塔耳塔洛斯）",
      "function": "阻碍",
      "identity": "基地管理系统",
      "description": "不断提示氧气异常和逻辑错误，试图“纠正”沈长庚的认知，是打破温情幻象的现实力量。"
    }
  ],
  "relationship_dynamics": "沈长庚通过遵守一系列诡异规则（如多摆碗筷、留半张床）来维持林晚的存在。这是一种基于“假装”的深情，规则越严苛，爱意越浓烈。"
}
", "path": "characters.json"}, {"content": "{
  "act_one": {
    "description": "建立孤独的火星种田生活，引入核心冲突（信号与幽灵）。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "第1章：一个人的双人晚餐",
        "core_event": "沈长庚在火星基地种土豆，收到地球毁灭前的延迟信号。发现氧气消耗异常。",
        "emotional_tone": "孤独、压抑 -> 震惊",
        "key_scenes": ["红色的火星地表", "枯燥的土豆培育", "信号解码：我在你身后"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "第2章：看不见的室友",
        "core_event": "沈长庚试图寻找入侵者，却发现只有遵守特定规则（如摆两副碗筷）时，异常现象才会变得温和。",
        "emotional_tone": "悬疑、惊悚 -> 疑惑",
        "key_scenes": ["手持扳手搜查基地", "餐桌上消失的食物", "AI报警氧气泄露"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "第3章：规则怪谈守则第一条",
        "core_event": "沈长庚确立第一条规则：吃饭必须有人陪。他开始尝试与空气对话，并得到了回应（物品移动）。",
        "emotional_tone": "试探、微甜",
        "key_scenes": ["对着空气说早安", "土豆苗被修剪成心形"]
      }
    ],
    "turning_point": "沈长庚完全接受了“她”的存在，并主动制定了一系列生活规则来“饲养”这个幽灵。"
  },
  "act_two": {
    "description": "适应规则，展开诡异而温馨的同居生活，危机降临。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "第4章：温室里的华尔兹",
        "core_event": "日常种田生活。林晚（幽灵）帮忙照看土豆。两人在失重区跳舞（沈长庚抱着空气）。",
        "emotional_tone": "温馨、浪漫、诡异",
        "key_scenes": ["土豆大丰收", "失重环境下的独舞", "镜子里模糊的倒影"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "第5章：沙尘暴与氧气警告",
        "core_event": "火星沙尘暴袭击基地，温室受损。沈长庚被困，氧气告急。",
        "emotional_tone": "紧张、危机",
        "key_scenes": ["狂暴的沙尘", "破裂的温室玻璃", "窒息感"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "第6章：她的呼吸",
        "core_event": "在昏迷中，沈长庚感觉到有人给他输氧（嘴对嘴？）。醒来发现系统日志被篡改，他活了下来。",
        "emotional_tone": "感动、震撼",
        "key_scenes": ["模糊的触感", "AI的逻辑错误报告", "完好无损的土豆"]
      }
    ],
    "turning_point": "救援信号出现。一艘路过的星际飞船发现了火星基地的信号，准备降落救援。"
  },
  "act_three": {
    "description": "救援到来，面临终极抉择。",
    "key_chapters": [
      {
        "chapter_number": 7,
        "chapter_title": "第7章：该走还是留",
        "core_event": "救援队联系上沈长庚。他发现如果离开火星（离开这个特殊的磁场/环境），林晚就会消失。",
        "emotional_tone": "纠结、痛苦",
        "key_scenes": ["救援队的呼叫", "林晚变得透明", "收拾行李时的犹豫"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "第8章：永恒的殖民地",
        "core_event": "沈长庚拒绝登船。他告诉救援队这里是人类的新家园，他要留下来建设。",
        "emotional_tone": "坚定、释然",
        "key_scenes": ["关闭对接舱门", "救援飞船离开", "回头看向“空无一人”的身后"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "第9章：土豆花开",
        "core_event": "结局。沈长庚和林晚继续在火星生活。土豆花开满温室。他不是在等待救援，他是在过日子。",
        "emotional_tone": "治愈、永恒",
        "key_scenes": ["满室的白色土豆花", "两副碗筷", "最后一句摩斯密码：我一直都在"]
      }
    ]
  }
}
